// Golden-master equivalence between the read-only original daily strategy (src/app/allin-original.ts)
// and the parameterized working copy (src/app/allIn-optimizable.ts).
//
// Both are run through their own command entry points on the same data file and date range, and every
// output file (trades.csv, daily.csv, states.csv, episodes.csv, summary.json) and every console line must
// be byte-identical. Away from the defaults, a temporary variant of the original is generated by replacing
// only its constant declarations (and the one log line that spells out "38%") in a scratch copy; the
// original file itself is only ever read.
import { createHash } from 'node:crypto';
import fs from 'fs-extra';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import optimizable, { type AllInParams, originalParams, tenthsToFraction } from '../app/allIn-optimizable.ts';
import type { Manifest } from './data/prepare.ts';
import { scenarios, writeFixture } from './fixtures.ts';
import { defaultParameterSpace, genomeToParams, gridSize } from './params.ts';
import { Rng } from './rng.ts';

// The original as committed in b7abde6. Any change to these bytes fails the golden master.
export const originalFile = 'src/app/allin-original.ts';
export const originalSha256 = '42f2b7e7be4ef99e1af6c4fe113dd8da9ed4d329d2fe0564463db80b87f449e2';
export const originalGitBlob = '6cdebca1c3590094894df1a9267d8d57cc47e210';

export const outputFiles = ['trades.csv', 'daily.csv', 'states.csv', 'episodes.csv', 'summary.json'];

export const sha256File = async (file: string) =>
  createHash('sha256')
    .update(await fs.readFile(file))
    .digest('hex');

export const verifyOriginalUnchanged = async () => {
  const actual = await sha256File(originalFile);

  if (actual !== originalSha256) {
    throw new Error(`${originalFile} has changed: sha256 ${actual}, expected ${originalSha256}`);
  }

  return actual;
};

type Runner = (...args: string[]) => Promise<void>;

const captureConsole = async (run: () => Promise<void>) => {
  const lines: string[] = [];
  const info = console.info;

  console.info = (...args: unknown[]) => {
    lines.push(args.map(String).join(' '));
  };

  try {
    await run();
  } finally {
    console.info = info;
  }

  return lines;
};

// Builds a scratch copy of the original with different constants. Only the constant declarations change.
export const writeOriginalVariant = async (params: AllInParams, dir: string) => {
  let source = await fs.readFile(originalFile, 'utf8');
  const replace = (pattern: RegExp, replacement: string) => {
    if (!pattern.test(source)) {
      throw new Error(`Variant pattern not found: ${pattern}`);
    }

    source = source.replace(pattern, replacement);
  };

  replace(/const tickWindowSize = 90;/, `const tickWindowSize = ${params.lookbackSessions};`);
  replace(/const targetPercentChange = 0\.1;/, `const targetPercentChange = ${tenthsToFraction(params.dipTenths)};`);
  replace(
    /const trailingStopPercentage = 0\.08;/,
    `const trailingStopPercentage = ${tenthsToFraction(params.trailingStopTenths)};`
  );
  replace(/const maximumHoldDays = 15;/, `const maximumHoldDays = ${params.maximumHoldDays};`);
  replace(
    /const materialLossThreshold = 0\.005;/,
    `const materialLossThreshold = ${tenthsToFraction(params.materialLossTenths)};`
  );
  replace(
    /const lowerPriceReentry = 0\.03;/,
    `const lowerPriceReentry = ${tenthsToFraction(params.lowerReentryTenths)};`
  );
  replace(/const retraceFraction = 0\.38;/, `const retraceFraction = ${tenthsToFraction(params.retraceTenths)};`);
  replace(
    /\(38% of the way back from the episode low/,
    '(${formatPercent(retraceFraction)} of the way back from the episode low'
  );

  const hash = createHash('sha256').update(source).digest('hex').slice(0, 16);
  const file = path.resolve(dir, `allin-variant-${hash}.ts`);

  await fs.ensureDir(dir);
  await fs.writeFile(file, source);

  return file;
};

export interface GoldenCase {
  name: string;
  symbol: string;
  dataFile: string;
  startDate?: string;
  endDate?: string;
  params?: AllInParams; // omitted: original defaults against the original file itself
}

export interface GoldenCaseResult {
  name: string;
  params: AllInParams;
  usedVariant: boolean;
  identical: boolean;
  differences: string[];
  consoleLines: number;
  fileBytes: Record<string, number>;
  summary: Record<string, unknown>;
}

const firstDifference = (a: string, b: string) => {
  const linesA = a.split('\n');
  const linesB = b.split('\n');

  for (let index = 0; index < Math.max(linesA.length, linesB.length); index++) {
    if (linesA[index] !== linesB[index]) {
      return `line ${index + 1}: original ${JSON.stringify(linesA[index])} vs copy ${JSON.stringify(linesB[index])}`;
    }
  }

  return 'no line difference';
};

export const runGoldenCase = async (testCase: GoldenCase, scratchDir: string): Promise<GoldenCaseResult> => {
  const params = testCase.params ?? { ...originalParams };
  const isDefault = JSON.stringify(params) === JSON.stringify(originalParams);
  let original: Runner;

  if (isDefault) {
    original = (await import(pathToFileURL(path.resolve(originalFile)).href)).default as Runner;
  } else {
    const variant = await writeOriginalVariant(params, path.join(scratchDir, 'variants'));

    original = (await import(pathToFileURL(variant).href)).default as Runner;
  }

  const caseDir = path.join(scratchDir, 'cases', testCase.name);
  const originalDir = path.join(caseDir, 'original');
  const copyDir = path.join(caseDir, 'copy');

  await fs.remove(caseDir);

  const args = [testCase.symbol, testCase.startDate ?? '-', testCase.endDate ?? '-', testCase.dataFile];
  const originalLines = await captureConsole(() => original(...args, originalDir));
  const copyLines = await captureConsole(() =>
    (optimizable as Runner)(...args, copyDir, isDefault ? '-' : JSON.stringify(params))
  );

  const differences: string[] = [];
  const fileBytes: Record<string, number> = {};
  // The data file path is printed by both; everything else must match exactly.
  const originalText = originalLines.join('\n').replaceAll(originalDir, '<out>');
  const copyText = copyLines.join('\n').replaceAll(copyDir, '<out>');

  if (originalText !== copyText) {
    differences.push(`console: ${firstDifference(originalText, copyText)}`);
  }

  for (const name of outputFiles) {
    const a = await fs.readFile(path.join(originalDir, name), 'utf8');
    const b = await fs.readFile(path.join(copyDir, name), 'utf8');

    fileBytes[name] = a.length;

    if (a !== b) {
      differences.push(`${name}: ${firstDifference(a, b)}`);
    }
  }

  const summary = JSON.parse(await fs.readFile(path.join(originalDir, 'summary.json'), 'utf8'));

  return {
    name: testCase.name,
    params,
    usedVariant: !isDefault,
    identical: differences.length === 0,
    differences,
    consoleLines: originalLines.length,
    fileBytes,
    summary
  };
};

export interface GoldenSuiteOptions {
  manifest: Manifest;
  researchEnd: string; // every case ends on or before this date, so no holdout P&L is computed
  scratchDir: string;
  variantsPerSymbol: number;
  log?: (line: string) => void;
}

const hashOutputs = async (dir: string) =>
  Object.fromEntries(
    await Promise.all(outputFiles.map(async (name) => [name, await sha256File(path.join(dir, name))]))
  );

// The full equivalence suite: repository files, every prepared Stooq series, date-filtered windows,
// synthetic edge cases and random parameter variants.
export const runGoldenSuite = async (options: GoldenSuiteOptions) => {
  const log = options.log ?? (() => {});
  const cases: GoldenCase[] = [];
  const end = options.researchEnd;

  cases.push({
    name: 'repo-VGT-2016-2026-default-start',
    symbol: 'VGT',
    dataFile: 'data/VGT/VGT-2016-2026.csv',
    endDate: end
  });
  cases.push({ name: 'repo-VGT-2005-2026', symbol: 'VGT', dataFile: 'data/VGT/VGT-2005-2026.csv', endDate: end });
  cases.push({ name: 'repo-QQQ-1999-2015', symbol: 'QQQ', dataFile: 'data/QQQ/QQQ-1999-2015.csv' });

  for (const [symbol, entry] of Object.entries(options.manifest.entries)) {
    if (entry.status === 'ok' && entry.processed) {
      cases.push({ name: `stooq-${symbol}-to-${end}`, symbol, dataFile: entry.processed.path, endDate: end });
    }
  }

  const vgt = options.manifest.entries.VGT?.processed?.path;

  if (vgt) {
    cases.push({
      name: 'stooq-VGT-2014-2018',
      symbol: 'VGT',
      dataFile: vgt,
      startDate: '2014-01-01',
      endDate: '2018-12-31'
    });
    cases.push({
      name: 'stooq-VGT-2020-only',
      symbol: 'VGT',
      dataFile: vgt,
      startDate: '2020-01-01',
      endDate: '2020-12-31'
    });
    cases.push({
      name: 'stooq-VGT-2008-2009',
      symbol: 'VGT',
      dataFile: vgt,
      startDate: '2008-01-01',
      endDate: '2009-12-31'
    });
  }

  const fixtureDir = path.join(options.scratchDir, 'fixtures');

  for (const [name, bars] of Object.entries(scenarios())) {
    const file = path.join(fixtureDir, `${name}.csv`);

    await writeFixture(file, bars);
    cases.push({ name: `synthetic-${name}`, symbol: 'SYN', dataFile: file });
  }

  // Random grid parameter vectors against generated variants of the original.
  const variantFiles: [string, string][] = [
    ...(['VGT', 'NVDA', 'IWN'] as const)
      .map((symbol) => [symbol, options.manifest.entries[symbol]?.processed?.path] as [string, string | undefined])
      .filter((pair): pair is [string, string] => Boolean(pair[1])),
    ['SYN', path.join(fixtureDir, 'random-walk-3.csv')],
    ['SYN', path.join(fixtureDir, 'restriction-reentry-reset.csv')]
  ];

  for (const [symbol, file] of variantFiles) {
    const rng = Rng.from('golden-variants', symbol, file);

    for (let index = 0; index < options.variantsPerSymbol; index++) {
      const genome = defaultParameterSpace.specs.map((spec) => rng.int(gridSize(spec)));

      cases.push({
        name: `variant-${symbol}-${path.basename(file, '.csv')}-${index}`,
        symbol,
        dataFile: file,
        endDate: symbol === 'SYN' ? undefined : end,
        params: genomeToParams(defaultParameterSpace, genome)
      });
    }
  }

  const results = [];

  for (const testCase of cases) {
    const result = await runGoldenCase(testCase, options.scratchDir);
    const copyDir = path.join(options.scratchDir, 'cases', testCase.name, 'copy');

    results.push({
      ...result,
      dataFile: testCase.dataFile,
      dataSha256: await sha256File(testCase.dataFile),
      startDate: testCase.startDate ?? null,
      endDate: testCase.endDate ?? null,
      copyOutputSha256: await hashOutputs(copyDir),
      summary: {
        closedTrades: result.summary.closedTrades,
        openAtEnd: result.summary.openAtEnd,
        restrictions: result.summary.restrictions,
        lowerPriceReentries: result.summary.lowerPriceReentries,
        recoveryResets: result.summary.recoveryResets,
        lossesNotRestricted: result.summary.lossesNotRestricted,
        sessions: result.summary.sessions
      }
    });
    log(
      `${result.identical ? 'IDENTICAL' : 'DIFFERENT'} ${testCase.name}${result.differences.length ? `: ${result.differences[0]}` : ''}`
    );
  }

  return results;
};
